window.PROCESS={id:"learning-development",name:"Learning & Development",store:"hr-learning-development-v1",GENERIC:{human:"Keep this with people. AI can still help in the background, for example with notes and reminders.",augment:"Let AI prepare and a person decide. Start with drafts, summaries and suggestions.",automate:"Let a workflow handle it and spot-check the results. Make it easy for people to reach a person.",create:"AI does most of this activity. Look for new work or services this makes possible, and decide who owns them."},SHRM:"",WORLD:[{t:"71% of L&D professionals are exploring, experimenting with or integrating AI into their work, including creating training content, recommending learning paths and identifying skills gaps.",s:"LinkedIn Workplace Learning Report 2025",h:""},{t:"The World Economic Forum estimates 39% of workers' core skills will change by 2030, making reskilling a central L&D challenge.",s:"WEF Future of Jobs Report 2025",h:""}],PRESETS:[{n:"Find skills gaps and learning needs",st:"Plan",h:2,t:"emerging",s:!1,th:"AI can pull together role skills, performance themes and survey comments to suggest where gaps may be. A person checks the picture with managers and decides what matters.",g:["Workday Skills Cloud","Eightfold AI","Degreed"],r:["Darwinbox","Mercer Mettl"]},{n:"Match the learning plan to strategy and budget",st:"Plan",h:1.5,t:"emerging",s:!1,th:"AI can draft a learning plan from business goals and past spending. Leaders decide what to fund and what to stop.",g:["Microsoft 365 Copilot","Workday HCM","Cornerstone"],r:["Darwinbox"]},{n:"Set learning goals and how success will be measured",st:"Plan",h:1,t:"emerging",s:!1,th:"AI can suggest clear goals and measures from similar programmes. People decide what success means here.",g:["Microsoft 365 Copilot","Docebo"],r:["Darwinbox"]},{n:"Plan for global and local needs",st:"Plan",h:.5,t:"emerging",s:!1,th:"AI can help check local rules, languages and holidays. People who know the place decide what fits.",g:["Docebo","Workday HCM","Microsoft 365 Copilot"],r:["Darwinbox","Keka"]},{n:"Design the learning programme",st:"Design and build",h:2,t:"emerging",s:!1,th:"AI can suggest outlines, objectives and activities. The learning designer decides what will help adults learn and use it at work.",g:["Articulate 360","Microsoft 365 Copilot","360Learning"],r:["upGrad","NIIT"]},{n:"Create and update content",st:"Design and build",h:2.5,t:"use",s:!1,th:"AI can draft text, quizzes, scripts and videos quickly. A subject expert checks accuracy and a designer checks that it teaches well.",g:["Articulate 360","Synthesia","Microsoft 365 Copilot","Sana"],r:["upGrad","NIIT"]},{n:"Choose how it is delivered",st:"Design and build",h:1,t:"emerging",s:!1,th:"AI can compare options such as self-study, classroom, on-the-job and blended. A person decides what suits the learners and the budget.",g:["Docebo","Cornerstone","Degreed"],r:["upGrad","NIIT"]},{n:"Make learning accessible and fair",st:"Design and build",h:1,t:"emerging",s:!1,th:"AI can add captions, plain-language versions and reading support. A person arranges adjustments and checks that no group is left behind.",g:["Microsoft 365 Copilot","Articulate 360","Docebo"],r:["Darwinbox"]},{n:"Pilot test and improve",st:"Design and build",h:.5,t:"emerging",s:!1,th:"AI can summarise pilot feedback and point out patterns. People decide what to change.",g:["Qualtrics EmployeeXM","Culture Amp","Docebo"],r:["Darwinbox"]},{n:"Build and keep a skills map",st:"Design and build",h:.5,t:"emerging",s:!1,nw:!0,th:"AI can suggest skills for roles and people from job descriptions and work records. This is a new way of seeing capability, and it must be checked and shared openly.",g:["Workday Skills Cloud","Eightfold AI","Degreed","Gloat"],r:["Darwinbox"]},{n:"Schedule sessions and enrol people",st:"Deliver",h:1.5,t:"use",s:!1,th:"Platforms can book rooms and trainers, open enrolment and send invitations. A person steps in for clashes and special cases.",g:["Docebo","Cornerstone","Workday Learning","SAP SuccessFactors Learning"],r:["Darwinbox","Keka","Zoho People"]},{n:"Run live sessions and coach",st:"Deliver",h:2.5,t:"not",s:!1,th:"Teaching and coaching are human. AI can prepare notes, handouts and practice scenarios, and capture questions afterwards.",g:["Microsoft 365 Copilot","Microsoft Teams","Mentimeter"],r:["NIIT","upGrad"]},{n:"Assign courses and send reminders",st:"Deliver",h:1.5,t:"use",s:!1,th:"Platforms assign courses by role and send reminders on a schedule. A person checks the rules and steps in when someone is stuck.",g:["Docebo","Cornerstone","Workday Learning","KnowBe4"],r:["Darwinbox","Keka"]},{n:"Answer learner questions",st:"Deliver",h:1.5,t:"use",s:!1,th:"A chat assistant can answer common questions from approved content at any hour. A named person handles anything personal or unclear.",g:["Microsoft 365 Copilot","Sana","ServiceNow","Moveworks"],r:["Leena AI","Darwinbox"]},{n:"Support on-the-job learning with managers",st:"Deliver",h:1.5,t:"not",s:!1,th:"Most learning happens at work. AI can give managers prompts and ideas. The real help is a manager who gives time, feedback and stretch work.",g:["Microsoft 365 Copilot","Degreed","Lattice"],r:["Darwinbox"]},{n:"Personalised learning paths",st:"Deliver",h:1,t:"emerging",s:!1,nw:!0,th:"AI can suggest a learning path from a person's role, skills and goals. This is a new service, and it must be easy to say no to.",g:["Degreed","Sana","LinkedIn Learning","Coursera for Business"],r:["upGrad","NIIT"]},{n:"Individual development plans",st:"Careers and leaders",h:2,t:"emerging",s:!1,th:"AI can draft a plan from a person's goals, role and skills, and suggest learning and projects. The employee and manager agree what is right.",g:["Degreed","Lattice","Leapsome","Microsoft 365 Copilot"],r:["Darwinbox","Keka"]},{n:"Career conversations",st:"Careers and leaders",h:1,t:"not",s:!1,th:"AI can help a manager prepare questions and a summary of achievements. The conversation about hopes and next steps is human.",g:["Lattice","Degreed","Microsoft 365 Copilot"],r:["Darwinbox"]},{n:"Match people to internal roles, projects and mentors",st:"Careers and leaders",h:1.5,t:"emerging",s:!1,nw:!0,th:"A talent marketplace can show people roles, projects and mentors that fit their skills and interests. This is a new way to open doors, and it needs fair, open rules.",g:["Gloat","Eightfold AI","Fuel50","Workday Skills Cloud"],r:["Darwinbox"]},{n:"Mentoring and coaching programmes",st:"Careers and leaders",h:1,t:"emerging",s:!1,th:"AI can suggest matches from goals and skills and remind people to meet. The relationship itself is human.",g:["Chronus","Together","MentorcliQ","Microsoft 365 Copilot"],r:["Darwinbox"]},{n:"Identify and develop high-potential people and future leaders",st:"Careers and leaders",h:1.5,t:"not",s:!1,th:"Talent reviews are high-impact. AI can bring evidence together and flag gaps in who is being considered. Leaders and HR decide, and must be able to explain why.",g:["Workday HCM","SAP SuccessFactors","Visier","Eightfold AI"],r:["Darwinbox"]},{n:"Leadership assessments and feedback",st:"Careers and leaders",h:1,t:"emerging",s:!1,th:"AI can summarise multi-rater feedback and point out themes. A coach helps the leader make sense of it. Results must stay private and be used to develop, not to punish.",g:["Korn Ferry","Culture Amp","Qualtrics EmployeeXM","Microsoft 365 Copilot"],r:["Mercer Mettl"]},{n:"Plan leader development across countries",st:"Careers and leaders",h:.5,t:"emerging",s:!1,th:"AI can help check local needs and translate materials. People who know each place agree what leaders should be like and how they grow.",g:["Docebo","Microsoft 365 Copilot","Workday HCM"],r:["Darwinbox"]},{n:"Track completion and keep records",st:"Measure and share",h:1.5,t:"use",s:!1,th:"Platforms track who took what and keep certificates. A person checks gaps and handles audits.",g:["Docebo","Cornerstone","Workday Learning","SAP SuccessFactors Learning"],r:["Darwinbox","Keka","Zoho People"]},{n:"Evaluate whether training worked",st:"Measure and share",h:1.5,t:"emerging",s:!1,th:"AI can combine feedback, test results and work data and point out patterns. People decide what the results mean and what to change.",g:["Docebo","Degreed","Qualtrics EmployeeXM","Visier"],r:["Darwinbox","Mercer Mettl"]},{n:"Report learning impact to leaders",st:"Measure and share",h:1,t:"emerging",s:!1,th:"AI can draft a clear report and charts. A person adds the story and decides what to say.",g:["Visier","Microsoft 365 Copilot","Workday HCM"],r:["Darwinbox"]},{n:"Capture and share organisational knowledge",st:"Measure and share",h:1.5,t:"emerging",s:!1,nw:!0,th:"AI can turn meetings, documents and expert talks into searchable summaries and short lessons. This is a new way to keep knowledge when people move on.",g:["Glean","Microsoft 365 Copilot","Sana","Notion"],r:["Zoho People"]},{n:"Manage the learning platform and vendors",st:"Throughout",h:1.5,t:"use",s:!1,th:"AI can help check contracts and compare vendors. A person chooses suppliers and manages the relationship.",g:["Docebo","Cornerstone","Workday Learning","Microsoft 365 Copilot"],r:["Darwinbox","Keka","Zoho People"]},{n:"Manage the learning budget",st:"Throughout",h:.5,t:"use",s:!1,th:"Systems track spend and show forecasts. A person decides what to approve and cuts.",g:["Workday HCM","SAP SuccessFactors","Microsoft 365 Copilot"],r:["Darwinbox","Zoho People"]},{n:"Keep mandatory and compliance training on track",st:"Throughout",h:1,t:"use",s:!1,th:"Systems assign required training and chase completion. A person explains why it matters and deals with people who are stuck.",g:["KnowBe4","NAVEX","Cornerstone","Docebo"],r:["Darwinbox","Keka"]},{n:"Explain AI use to learners and test the AI tools",st:"Throughout",h:.5,t:"not",s:!1,nw:!0,th:"This is a new task AI makes necessary. HR explains in plain words where AI is used in learning and how to reach a person. HR tests the tools for accuracy and fairness.",g:["Microsoft 365 Copilot","ServiceNow"],r:["Darwinbox"]},{n:"Learn the tools and check AI's work",st:"Throughout",h:.5,t:"emerging",s:!1,nw:!0,th:"AI changes what learning professionals do. Time goes into checking AI output, learning the tools and sharing what works.",g:["Microsoft 365 Copilot","Articulate 360"],r:["Darwinbox"]}],TERMS:[["LMS","Learning management system. The platform that holds courses, enrolments and records."],["ADDIE","A common five-step way to build training: analysis, design, development, implementation and evaluation."],["70-20-10","A rule of thumb that most learning comes from work, some from other people, and the least from formal courses."],["Individual development plan","A plan, agreed between a person and their manager, for how the person will grow."],["Talent marketplace","A system that matches people to roles, projects and mentors inside the organisation."],["Skills map","A picture of the skills people have and the skills the organisation needs."],["Blended learning","A mix of live teaching, self-study and learning at work."],["Microlearning","Very short lessons, often a few minutes, that people can use between tasks."],["Mentoring","A longer relationship where an experienced person helps someone else grow, often not their manager."],["Coaching","Focused one-to-one help to reach a specific goal, often for a shorter period."],["Action learning","Learning by working on a real business problem, with time to reflect."],["Human in the loop","A person checks or decides before AI output is used or acted on."],["Generative AI","AI that writes text, makes images or answers questions."]],ORGS:{"Workday Skills Cloud":["Global","Skills data inside Workday, used to suggest roles, learning and projects"],"Eightfold AI":["Global","Finds and matches people by their skills"],Degreed:["Global","Skills and learning platform"],Darwinbox:["Regional","HR suite based in India"],"Mercer Mettl":["Regional","Online assessments, founded in India, now part of Mercer"],"Microsoft 365 Copilot":["Global","AI help for drafting and summaries in Word, Outlook and Teams"],"Workday HCM":["Global","HR suite with onboarding, payroll and records in one place"],Cornerstone:["Global","Learning and talent platform"],Docebo:["Global","Learning platform with AI course suggestions"],Keka:["Regional","HR and payroll software from India"],"Articulate 360":["Global","Tools for building online courses, with AI writing help"],"360Learning":["Global","Collaborative learning platform where experts build courses with their teams"],upGrad:["Regional","Online learning and degree programmes from India"],NIIT:["Regional","Training and corporate learning provider from India"],Synthesia:["Global","Makes training videos with AI presenters from a script"],Sana:["Global","AI learning and knowledge platform that answers questions from company content"],"Qualtrics EmployeeXM":["Global","Employee surveys and listening"],"Culture Amp":["Global","Employee surveys and feedback"],Gloat:["Global","Talent marketplace that matches people to internal roles and projects"],"Workday Learning":["Global","Learning module inside Workday HCM"],"SAP SuccessFactors Learning":["Global","Learning module inside SAP SuccessFactors"],"Zoho People":["Regional","HR software from India-based Zoho"],"Microsoft Teams":["Global","Chat, calls and meetings"],Mentimeter:["Global","Live polls and quizzes for sessions and workshops"],KnowBe4:["Global","Security awareness training"],ServiceNow:["Global","Service desk and HR service delivery, with case tracking"],Moveworks:["Global","AI assistant for employee requests and IT help"],"Leena AI":["Regional","Chat assistant for employee questions, started in India"],Lattice:["Global","Goals, feedback and performance reviews"],"LinkedIn Learning":["Global","Online courses"],"Coursera for Business":["Global","Online courses from universities and companies for employees"],Leapsome:["Global","Goals, feedback and engagement"],Fuel50:["Global","Talent marketplace and career pathing platform"],Chronus:["Global","Mentoring and buddy programme software"],Together:["Global","Mentoring programme software"],MentorcliQ:["Global","Mentoring programme software with matching and tracking"],"SAP SuccessFactors":["Global","HR suite from SAP with an onboarding module"],Visier:["Global","Reports and numbers about the workforce"],"Korn Ferry":["Global","Leadership assessments and talent tools"],Glean:["Global","Work search and assistant across company tools"],Notion:["Global","Shared workspace for notes, documents and a searchable knowledge base"],NAVEX:["Global","Ethics and compliance training and policy tools"]},BUCKETS:[["Learning platforms and records","Where courses, enrolments, reminders and completion records live.",["Docebo","Cornerstone","Workday Learning","SAP SuccessFactors Learning","Degreed","Darwinbox","Keka","Zoho People"],"Enrolling people, sending reminders and keeping records.","Handling clashes and being kind to people who are behind."],["Content and course creation","Writing, video and course-building help.",["Articulate 360","Synthesia","360Learning","Sana","LinkedIn Learning","Coursera for Business","upGrad","NIIT"],"First drafts of text, quizzes and videos, and updating content.","Checking accuracy and deciding what actually teaches well."],["Skills and talent marketplaces","Seeing skills and matching people to roles, projects and learning.",["Workday Skills Cloud","Eightfold AI","Gloat","Fuel50","Workday HCM","SAP SuccessFactors"],"Suggesting skills, roles and projects from data.","Letting people correct their profile, and deciding who moves."],["Mentoring, coaching and careers","Connecting people and supporting growth conversations.",["Chronus","Together","MentorcliQ","Lattice","Leapsome"],"Matching suggestions, reminders and prompts.","The relationship, and the career conversation itself."],["Leadership feedback and assessment","Feedback, surveys and assessments for leaders.",["Korn Ferry","Culture Amp","Qualtrics EmployeeXM","Mercer Mettl","Visier"],"Collecting feedback and finding themes in comments.","Explaining results with care, and deciding what to do."],["Questions, knowledge and sessions","Answering questions, finding what people know and running sessions.",["Microsoft 365 Copilot","Glean","Notion","ServiceNow","Moveworks","Leena AI","Mentimeter","Microsoft Teams"],"Answering common questions and finding documents.","Personal or sensitive questions, and checking accuracy."],["Compliance training","Required courses such as security, ethics and data protection.",["KnowBe4","NAVEX"],"Assigning courses and chasing completion.","Explaining why it matters, and helping people who are stuck."]],DEFS:{chances:["Chances","AI could decide, rank, filter or score who moves forward, who is turned down, or who gets an offer. It also counts if AI sets the must-haves or scoring those decisions use, or tells people the result."],privacy:["Privacy","AI would handle sensitive personal data: ID and documents, health or disability details, background and reference results, recordings and notes, group data such as gender, or consent and how long data is kept."]},UC:{"Find skills gaps and learning needs":{goal:"Find out what skills the organisation, teams and individuals will need, so learning time goes where it counts.",today:"Managers often ask for a course when the real problem is something else. Employees may not be asked what they need, and gaps show up late.",who:"Employees, managers, HR and the learning team",keep:"Asking managers and employees what is really getting in the way, and deciding which needs matter most",risk:"Skills inferred from data can be wrong or out of date. A gap labelled against a person can follow them unfairly",safe:"Use skills data to start the conversation, never to label a person. Check suggestions with the manager and the employee.",pilot:"Ask AI to summarise last year's survey comments and review notes for one team, then compare with what the manager says",owner:"Learning lead, HR"},"Match the learning plan to strategy and budget":{goal:"Make sure learning supports where the business is going and fits the money available.",today:"Plans are often built from last year's list. Budgets are tight and the link to strategy is hard to show.",who:"Leaders, HR and the learning team",keep:"Deciding what to fund, what to stop and what trade-offs are acceptable",risk:"A plan that looks neat but is not tied to real business goals. Over-trust in a tool's cost estimates",safe:"Keep a named owner for each priority. Check any AI estimate against finance records.",pilot:"Ask AI to draft three plan options from the business goals, then review them with one leader",owner:"Learning lead, finance partner"},"Set learning goals and how success will be measured":{goal:"Agree before the work starts what a good result looks like, so it can be checked later.",today:"Goals are often vague, such as 'improve skills', so nobody can tell later if it worked.",who:"Learning team, managers and sponsors",keep:"Agreeing what success means with the people who will live with it",risk:"Goals that measure what is easy to count rather than what matters",safe:"Link each goal to a change in work behaviour, not only to course completion.",pilot:"Draft goals and measures for one programme with AI, then ask the sponsor what is missing",owner:"Learning lead"},"Plan for global and local needs":{goal:"Make sure learning works across countries and sites without copying headquarters habits blindly.",today:"Content built at headquarters may not fit local law, language or culture. Some countries expect face-to-face learning.",who:"Learners in every location and local HR",keep:"Judging what fits local culture, law and expectations",risk:"Stereotypes about countries. Translated content that reads badly or misses a legal rule",safe:"Ask local HR to review. Use real local data, not assumptions.",pilot:"Machine-translate one course, then ask two local colleagues what reads wrongly",owner:"Learning lead, local HR"},"Design the learning programme":{goal:"Turn a need into a clear, useful programme that people can use at work.",today:"Designers are often asked for courses quickly. Learners sit through content that is not tied to their job.",who:"Learners, managers and learning designers",keep:"Choosing what people really need to practise, and how to make it relevant to them",risk:"Content that is too long or too generic. Treating every learner as the same",safe:"Start from the work behaviour to change. Test with real learners before roll-out.",pilot:"Ask AI for two outlines for one topic, then ask five learners which feels more useful",owner:"Learning designer"},"Create and update content":{goal:"Produce accurate, clear content and keep it up to date without it taking weeks.",today:"Content goes stale. Experts have little time. Updating takes as long as building.",who:"Learners, subject experts and designers",keep:"Checking accuracy and deciding what is safe and right to teach",risk:"Confident but wrong content. Copied or unlicensed material. Content that reflects bias",safe:"A subject expert signs off every item. Check sources and licences. Say when AI helped to write it.",pilot:"Let AI draft one quiz and one short script, then have an expert mark errors",owner:"Learning designer, subject expert"},"Choose how it is delivered":{goal:"Pick the format that will work for these learners, in this place, at this cost.",today:"Formats are often chosen by habit. Some groups cannot attend live or lack a computer.",who:"Learners and the learning team",keep:"Judging who can attend, what they trust and what fits the work",risk:"Assuming everyone can learn online. Ignoring shifts and low connectivity",safe:"Ask a few learners first. Always offer a route for people who cannot use the main format.",pilot:"List the format choices with AI for one programme, then ask a sample of learners what they could use",owner:"Learning lead"},"Make learning accessible and fair":{goal:"Make sure everyone can take part, including people who need adjustments.",today:"People may not ask for help. Content is built for one kind of learner. Adjustments arrive late.",who:"Learners who need adjustments, and learners in every group",keep:"Talking with someone about what helps, and agreeing an adjustment",risk:"Auto-captions or translations that are wrong. Revealing a health need. Treating adjustments as a burden",safe:"Keep needs private and only for those who must know. Offer an easy, respectful way to ask.",pilot:"Add AI captions and a plain-language summary to one course, then ask users of assistive tools what works",owner:"Learning lead, HR"},"Pilot test and improve":{goal:"Try a programme with a small group first, so mistakes are found early and cheaply.",today:"Pilots are often skipped when time is short. Feedback is not acted on.",who:"Pilot learners, trainers and the designer",keep:"Listening to pilot learners and deciding what to change",risk:"Treating a small, friendly pilot group as typical",safe:"Include some sceptical and busy learners. Tell pilot learners what changed.",pilot:"Run a 10-person pilot and have AI group the comments, then compare with your own reading",owner:"Learning designer"},"Build and keep a skills map":{goal:"Hold a clear picture of the skills the organisation has and needs, and keep it up to date.",today:"Skills lists are out of date almost as soon as they are written. People are not sure how they are used.",who:"Employees, managers and HR",keep:"Agreeing what skills mean here and letting people correct their own profile",risk:"Inferred skills that are wrong or unfair. People feeling watched. Using the map to rank people without telling them",safe:"Let people see and correct their own skills. Use the map to open doors, not to judge.",pilot:"Let AI suggest skills for one job family, then ask ten employees to correct their own profile",owner:"HR, learning lead"},"Schedule sessions and enrol people":{goal:"Make it easy for people to find a session, sign up and turn up.",today:"People find out late, clash with work, or cannot see what is available.",who:"Learners, managers and the learning team",keep:"Handling clashes and special requests kindly",risk:"Sessions full of the wrong people. Managers who block time without discussion",safe:"Let managers and learners see why a session matters. Keep a manual route open.",pilot:"Let the platform send invitations and reminders for one programme and count no-shows",owner:"Learning administrator"},"Run live sessions and coach":{goal:"Help people learn by doing, with a trainer who can read the room.",today:"Learners remember the person more than the slides. Sessions run long and rarely allow practice.",who:"Learners and trainers",keep:"Reading the room, giving feedback and making it safe to try and fail",risk:"A trainer who relies on AI notes without thinking. Recording people without clear consent",safe:"Ask before recording. Never use AI notes to rate individuals.",pilot:"Use AI to prepare practice scenarios for one workshop, and ask learners if it felt realistic",owner:"Trainer"},"Assign courses and send reminders":{goal:"Make sure the right people get the right learning at the right time, without chasing.",today:"Reminders pile up and feel like nagging. Some people never see them.",who:"Learners, managers and administrators",keep:"Following up kindly when someone is stuck or overloaded",risk:"Constant reminders that cause stress. Wrong assignments from bad rules",safe:"Limit how often reminders go out. Check the assignment rules every few months.",pilot:"Cut reminders to one a week for one team, and check completion and how it felt",owner:"Learning administrator"},"Answer learner questions":{goal:"Help people find answers fast, such as how to join a course or where a certificate is.",today:"People send the same questions again and again. Answers depend on who is free.",who:"Learners and the learning team",keep:"Personal or sensitive questions, and anything the assistant is unsure about",risk:"A wrong answer given with confidence. No way to reach a person",safe:"Use approved content only. Always show how to reach a person.",pilot:"Let an assistant answer 20 common questions from the help page and have a person check every answer for a week",owner:"Learning administrator"},"Support on-the-job learning with managers":{goal:"Help managers turn everyday work into learning, because most learning happens on the job.",today:"Managers are busy and often unsure how to coach. Learning is seen as something that happens in a classroom.",who:"Employees and their managers",keep:"Giving time, feedback and stretch assignments, and caring whether the person grows",risk:"Managers who hand coaching to a tool. Stretch work with no support",safe:"Treat prompts as help, not a script. Check that stretch work is fair across groups.",pilot:"Send five managers a weekly coaching prompt written with AI, and ask what they used",owner:"Learning lead, line managers"},"Personalised learning paths":{goal:"Give each person a path that fits what they know and where they want to go.",today:"Everyone gets the same list of courses, whether they need them or not.",who:"Learners",keep:"Letting the person choose, and talking about what they really want",risk:"Suggestions that narrow a person's options unfairly. Using private data without clear permission",safe:"Say how suggestions are made. Make them easy to ignore. Do not use them for rating people.",pilot:"Offer AI path suggestions to 20 volunteers, and ask how many they used and how helpful they felt",owner:"Learning lead"},"Individual development plans":{goal:"Give each person a clear plan for how they will grow, with support from their manager.",today:"Plans are written once a year and forgotten. Employees are not sure what is open to them.",who:"Employees and managers",keep:"Agreeing the plan in a real conversation about hopes, strengths and limits",risk:"A plan that is generic or ignored. Private career hopes shared more widely than the employee expects",safe:"Keep plans private to the employee and manager unless the employee agrees. Review them during the year.",pilot:"Let AI draft a first plan for 10 volunteers, then ask the employee and manager how much they changed",owner:"Employee, manager, HR"},"Career conversations":{goal:"Help people talk honestly about where they want to go and what is possible.",today:"Many people have never had a real career conversation. Managers worry about promising what they cannot give.",who:"Employees and managers",keep:"Listening, being honest about what is possible, and keeping trust",risk:"Promising roles that do not exist. AI summaries that miss what matters to the person",safe:"Do not share career hopes beyond the manager and HR without permission.",pilot:"Give 10 managers an AI question list and ask afterwards what they used",owner:"Manager"},"Match people to internal roles, projects and mentors":{goal:"Help people find chances inside the organisation, and help the organisation use the skills it has.",today:"People hear about openings by chance. Managers hold on to good people. Talent leaves before it is seen.",who:"Employees, managers and hiring teams",keep:"Talking with current managers fairly, and deciding who moves",risk:"A ranking that people cannot see or challenge. Bias in who is shown what. Managers blocking moves",safe:"Show people why they are matched. Let them opt out. Keep a person accountable for each move decision.",pilot:"Let a marketplace suggest three projects to 20 volunteers, and compare who got offered what across groups",owner:"HR talent lead"},"Mentoring and coaching programmes":{goal:"Connect people with others who can help them grow, with clear goals and support.",today:"Matches are made by hand and may favour the already well-connected. Pairs stop meeting after a few weeks.",who:"Mentors, mentees and HR",keep:"Choosing to be a mentor or mentee, and building a relationship of trust",risk:"Matches that repeat old patterns. A mentor treated as a supervisor. Pressure to join",safe:"Joining is voluntary. Keep conversations private. Collect only light feedback on the programme.",pilot:"Let AI suggest matches for 10 pairs, and ask them after 6 weeks how well it worked",owner:"HR, programme lead"},"Identify and develop high-potential people and future leaders":{goal:"Spot and grow people who can lead in the future, fairly and openly.",today:"Choices are often based on who is visible. People who are not chosen may never know why.",who:"Employees, leaders and HR",keep:"Judging potential, giving honest feedback and explaining decisions",risk:"Bias in who is seen as high potential. Labels that follow people for years. Secret ratings",safe:"Do not let a tool decide. Check the mix of people chosen. Tell people how selection works.",pilot:"Compare AI evidence summaries with the usual list for one talent review, and ask what each missed",owner:"HR business partner, senior leaders"},"Leadership assessments and feedback":{goal:"Help leaders see their strengths and blind spots, and plan how to grow.",today:"Feedback can sting. Reports are long, and leaders may not know what to do next.",who:"Leaders, their teams and coaches",keep:"Explaining results kindly and helping the leader decide what to do",risk:"Feedback used to judge rather than develop. Comments identifying who said what",safe:"Keep reports confidential to the leader and coach. Keep comments anonymous.",pilot:"Have AI summarise themes in feedback for 5 leaders, and ask coaches whether they match the full reports",owner:"Coach, HR"},"Plan leader development across countries":{goal:"Build leaders who can work across cultures, without simply copying headquarters.",today:"Leadership criteria may reflect one culture. Local leaders may feel overlooked.",who:"Leaders in every country and local HR",keep:"Agreeing what good leadership means in each place",risk:"Assuming headquarters ways fit everywhere. Poor translations",safe:"Get local sign-off on leadership criteria. Ask international leaders what they need.",pilot:"Share draft leadership criteria with three countries and ask what does not fit",owner:"Learning lead, local HR"},"Track completion and keep records":{goal:"Know who has done what, and have proof when someone asks.",today:"Records sit in different places. Chasing certificates takes time.",who:"Learners, managers and auditors",keep:"Deciding what to keep, for how long, and handling audits",risk:"Keeping learner data longer than needed. Records used to judge people in ways they did not expect",safe:"Keep only what is needed. Set retention periods. Say how records are used.",pilot:"Check one programme's records for gaps with an automated report, and compare with a manual check",owner:"Learning administrator"},"Evaluate whether training worked":{goal:"Find out whether people learned, used it at work and made a difference.",today:"Many programmes are judged by smile sheets and completion only. Real results are rarely checked.",who:"Learners, managers, sponsors and the learning team",keep:"Deciding what counts as success and being honest when something did not work",risk:"Linking learning to performance in a way that is unfair or misleading. Collecting more personal data than needed",safe:"Evaluate programmes, not people. Use aggregated data.",pilot:"Combine feedback and 90-day manager comments for one programme with AI, and compare with a manual review",owner:"Learning lead"},"Report learning impact to leaders":{goal:"Show leaders in plain words what learning is doing for the business.",today:"Reports list activity, such as courses and hours, rather than results.",who:"Leaders and the learning team",keep:"Deciding what the numbers really mean and telling the honest story",risk:"Charts that look convincing but are misleading. Claims about impact that the data cannot support",safe:"Show how each number is made. Say what the data cannot show.",pilot:"Draft one quarterly report with AI, then ask a leader what they would act on",owner:"Learning lead"},"Capture and share organisational knowledge":{goal:"Keep what people know inside the organisation, so it is not lost when they leave.",today:"Knowledge lives in a few heads. When people retire or move, it goes with them.",who:"Employees, experts and new joiners",keep:"Deciding what is worth keeping and asking experts to share what they know",risk:"Wrong or outdated summaries presented as fact. Recording people without clear consent. Sensitive information appearing in search",safe:"Ask before recording. Give each knowledge item an owner and a review date.",pilot:"Capture three expert talks as AI summaries and ask new joiners whether they used them",owner:"Learning lead, subject experts"},"Manage the learning platform and vendors":{goal:"Keep the platform working, and choose suppliers who deliver value and treat data well.",today:"Platforms multiply, and vendors promise a lot. Learners get lost between systems.",who:"Learners, administrators and vendors",keep:"Choosing suppliers and holding them to account",risk:"Locked-in vendors. Vendor AI features that no one has tested. Data shared with suppliers without clear terms",safe:"Check data terms before signing. Test any AI feature before turning it on for everyone.",pilot:"Compare two platforms' AI features with a short checklist, and test each with five users",owner:"Learning administrator, procurement"},"Manage the learning budget":{goal:"Spend learning money on what matters, and show where it went.",today:"Spend is hard to see. Last-minute cuts hit learning first.",who:"Learning team and finance",keep:"Deciding what to protect and what to cut",risk:"Costs that look efficient but cut quality",safe:"Keep a named owner for each budget line.",pilot:"Build a spend dashboard for one quarter and ask finance if it matches their records",owner:"Learning lead, finance"},"Keep mandatory and compliance training on track":{goal:"Make sure required training, such as safety, ethics and data protection, is done on time.",today:"Mandatory courses feel like a chore, and people click through them.",who:"Employees, managers and compliance teams",keep:"Explaining why it matters and handling people who cannot finish",risk:"Treating a certificate as proof of understanding. Public shaming of late completers",safe:"Do not publish names. Check understanding, not just completion.",pilot:"Add two short scenario questions to one mandatory course and see what people get wrong",owner:"Compliance lead, learning administrator"},"Explain AI use to learners and test the AI tools":{goal:"Be open about where AI is used in learning, and make sure it works well and fairly.",today:"Learners are often unsure when AI is involved and what happens to their data.",who:"Learners and the learning team",keep:"Explaining honestly, listening to worries and deciding what to change",risk:"AI features switched on without anyone being told. No evidence that a tool was tested",safe:"Keep a short register of AI tools in learning, with a named owner for each.",pilot:"Write a one-page note on AI use in learning and ask ten learners what is still unclear",owner:"Learning lead, HR"},"Learn the tools and check AI's work":{goal:"Build the team's skill in using AI well, and keep humans accountable for the result.",today:"People are unsure what to trust and how to check it.",who:"The learning team",keep:"Judging what AI output is good enough, and asking why",risk:"Over-trusting AI output. Skills that fade when AI does the work",safe:"Check a sample of AI output every time. Share what goes wrong.",pilot:"Hold a monthly 30-minute session to share one AI success and one mistake",owner:"Learning lead"}},CRIT:{"Match people to internal roles, projects and mentors":[["chances"],"Who is shown a role or project can decide who gets a chance to grow."],"Identify and develop high-potential people and future leaders":[["chances"],"Being picked as high potential can change a person's career for years."],"Leadership assessments and feedback":[["chances","privacy"],"Results can shape promotion, and feedback is sensitive personal data."],"Build and keep a skills map":[["privacy"],"Skills inferred from work records are personal data, and may be wrong."],"Personalised learning paths":[["privacy"],"Paths are built from personal skills, goals and learning history."],"Make learning accessible and fair":[["privacy"],"Adjustments can reveal health or disability details."],"Individual development plans":[["privacy"],"Career hopes and development needs are private to the person."],"Track completion and keep records":[["privacy"],"Learning records are personal data that must be kept only as long as needed."],"Capture and share organisational knowledge":[["privacy"],"Recordings and notes can include personal or sensitive information."]},STEPS:{"Find skills gaps and learning needs":[["Collect role and skills information","automate",20,"Pulling role profiles and skills records together is routine."],["Summarise survey comments and review themes","augment",25,"AI summarises. A person reads the comments."],["Suggest likely skills gaps by team","augment",20,"AI suggests from skills data. A person checks it."],["Talk to managers and employees about what is needed","human",25,"People know what gets in the way. Listening is a human job."],["Decide which needs to act on first","human",10,"Choosing priorities is a judgement."]],"Match the learning plan to strategy and budget":[["Gather business goals and last year's learning data","automate",20,"Collecting data from existing systems is routine."],["Draft plan options and cost estimates","augment",30,"AI drafts options. A person checks the numbers."],["Agree priorities with leaders","human",35,"Trade-offs are decided in conversation."],["Record the plan and share it","automate",15,"Filing and sending are routine."]],"Set learning goals and how success will be measured":[["Suggest goals and measures from similar programmes","augment",35,"AI suggests. A person edits."],["Agree what success looks like with the sponsor","human",40,"Success is a shared agreement, not a template."],["Write the goals into the plan","augment",15,"AI tidies the wording."],["Set up the data to be collected","automate",10,"Setting up tracking is routine."]],"Plan for global and local needs":[["List local legal and language needs","augment",30,"AI lists. Local HR confirms."],["Translate and adapt content","augment",30,"AI translates. A local person checks it."],["Check fit with local culture and practice","human",30,"Only people who know the place can judge this."],["Schedule around local holidays and shifts","automate",10,"Calendars follow fixed rules."]],"Design the learning programme":[["Draft objectives and an outline","augment",30,"AI drafts from the need. The designer edits."],["Choose activities that build skill","human",25,"Good practice design is a human craft."],["Match content to adult learning principles","augment",15,"AI can check a draft against a checklist."],["Build a storyboard or action map","augment",20,"AI drafts a structure. The designer decides."],["Review with the sponsor and learners","human",10,"Feedback comes from conversation."]],"Create and update content":[["Draft text, quizzes and scripts","automate",25,"AI produces first drafts quickly."],["Turn documents into short lessons","augment",20,"AI summarises. A person shapes it."],["Check accuracy and sources","human",25,"Only a person can be accountable for what is taught."],["Produce video, voice or images","augment",15,"AI makes the first version. A person approves it."],["Flag out-of-date content","automate",15,"Checking dates and links is rules-based."]],"Choose how it is delivered":[["List delivery options and costs","augment",35,"AI compares. A person checks."],["Check access, shifts and technology","augment",20,"AI flags clashes. A person decides."],["Choose the blend","human",35,"Fit with people and the place needs a human decision."],["Book rooms, trainers and platforms","automate",10,"Booking is routine."]],"Make learning accessible and fair":[["Add captions, transcripts and plain-language versions","automate",30,"AI can produce these quickly."],["Check quality of captions and translations","augment",25,"AI checks. A person fixes what is wrong."],["Talk with learners about what helps","human",30,"A first conversation about needs should feel personal."],["Arrange agreed adjustments","augment",15,"AI tracks the arrangements. A person approves."]],"Pilot test and improve":[["Choose a pilot group","human",20,"Picking a mixed group needs judgement."],["Collect feedback","automate",25,"Sending short surveys is routine."],["Summarise themes in feedback","augment",30,"AI summarises. A person reads the comments."],["Decide what to change","human",25,"Choosing fixes is a decision."]],"Build and keep a skills map":[["Suggest skills from job descriptions and work records","create",35,"A new service: AI proposes a starting skills picture."],["Check the skills list with experts","human",25,"Experts know what the skills really mean."],["Let employees review and correct their profile","human",25,"People should own how they are described."],["Update the map from learning and projects","automate",15,"Updating records is routine."]],"Schedule sessions and enrol people":[["Book rooms, trainers and links","automate",30,"Booking follows fixed rules."],["Open enrolment and send invitations","automate",30,"Sending is routine."],["Suggest sessions that fit a person's role and calendar","augment",20,"AI suggests. The person chooses."],["Handle clashes and special requests","human",20,"Clashes need judgement and kindness."]],"Run live sessions and coach":[["Prepare handouts and practice scenarios","augment",25,"AI drafts. The trainer chooses."],["Teach and facilitate","human",45,"Learning comes from people in a room or on a call."],["Give feedback on practice","human",20,"Feedback needs care and context."],["Capture questions and follow-ups","augment",10,"AI can tidy notes. The trainer owns the follow-up."]],"Assign courses and send reminders":[["Assign courses by role, location and level","automate",35,"Assignment follows fixed rules."],["Send reminders and track progress","automate",30,"Reminders are routine."],["Write friendlier reminder messages","augment",15,"AI drafts. HR checks tone."],["Follow up with people who are stuck","human",20,"A conversation finds the real reason."]],"Answer learner questions":[["Answer common questions from approved content","automate",40,"Common questions have standard answers."],["Suggest answers for harder questions","augment",25,"AI drafts. A person checks it."],["Handle personal or sensitive questions","human",25,"Sensitive questions need a person."],["Spot repeated questions and fix the cause","create",10,"A new insight: repeated questions show where content is unclear."]],"Support on-the-job learning with managers":[["Share coaching prompts and tips with managers","augment",30,"AI drafts. HR chooses what to send."],["Suggest stretch assignments and projects","augment",25,"AI suggests. The manager decides."],["Give feedback and time to learn","human",35,"Support from a manager is human."],["Check that growth chances are shared fairly","augment",10,"AI compares groups. HR looks into gaps."]],"Personalised learning paths":[["Suggest a path from role, skills and goals","create",40,"A new service: a path that adapts to the person."],["Let the learner change or ignore it","human",25,"People own their own learning."],["Keep content in the path up to date","automate",20,"Updating links and content is routine."],["Check results for fairness","augment",15,"AI compares groups. A person reviews."]],"Individual development plans":[["Draft a first plan from goals, role and skills","augment",30,"AI drafts. The employee and manager edit."],["Suggest courses, projects and mentors","augment",20,"AI suggests. The person chooses."],["Agree the plan in a conversation","human",35,"Agreement is a conversation, not a form."],["Record the plan and send reminders","automate",15,"Filing and reminders are routine."]],"Career conversations":[["Prepare a summary of work and achievements","augment",25,"AI gathers what exists. The manager adds context."],["Suggest questions and possible paths","augment",20,"AI suggests. The manager chooses."],["Hold the conversation","human",45,"Career talk needs listening and honesty."],["Write up the next steps","augment",10,"AI tidies notes. Both people confirm them."]],"Match people to internal roles, projects and mentors":[["Suggest roles, projects and mentors","create",35,"A new service: people see chances they would not have found."],["Check that matches are fair across groups","augment",20,"AI compares groups. HR looks into gaps."],["Talk with the current manager","human",25,"A respectful conversation keeps trust."],["Decide on the move and support the person","human",20,"A move that affects someone's work is a human decision."]],"Mentoring and coaching programmes":[["Suggest matches from goals and interests","augment",30,"AI suggests. A person checks the fit."],["Ask mentors and mentees and confirm","human",25,"Asking someone to give their time is personal."],["Send reminders and meeting ideas","automate",25,"Reminders are routine."],["Collect light feedback on how it is going","augment",20,"Aggregate feedback only, never details of the chat."]],"Identify and develop high-potential people and future leaders":[["Gather performance and development evidence","automate",20,"Collecting records is routine."],["Summarise evidence for each person","augment",20,"AI summarises. A person checks it."],["Check who is missing from the list","augment",15,"AI flags gaps. HR looks into them."],["Decide who joins development programmes","human",30,"A decision that affects careers belongs to people."],["Give feedback to people who are not selected","human",15,"Honest feedback needs care."]],"Leadership assessments and feedback":[["Collect feedback from managers, peers and teams","automate",25,"Sending and collecting surveys is routine."],["Summarise themes and comments","augment",30,"AI summarises. A person reads the comments."],["Talk through the results with the leader","human",35,"A coach helps the leader make sense of it."],["Record the development plan","automate",10,"Filing is routine."]],"Plan leader development across countries":[["Compare leadership needs by country","augment",30,"AI compares. Local people confirm."],["Translate and adapt materials","augment",25,"AI translates. A local person checks."],["Agree criteria with international locations","human",35,"Agreement is a conversation across places."],["Schedule programmes across time zones","automate",10,"Scheduling follows fixed rules."]],"Track completion and keep records":[["Record completions and certificates","automate",45,"Systems record this automatically."],["Check records for gaps","automate",25,"Checking against a list is rules-based."],["Delete records when the retention period ends","automate",10,"Deletion follows a schedule, with a person approving the list."],["Prepare for audits and answer questions","human",20,"Audits need a person who can explain."]],"Evaluate whether training worked":[["Collect feedback and test results","automate",25,"Sending surveys and tests is routine."],["Combine learning and work data","augment",25,"AI finds patterns. A person checks they are fair."],["Talk with managers about what changed at work","human",25,"Managers see what changed."],["Decide what to keep, change or stop","human",25,"This is a decision about money and people."]],"Report learning impact to leaders":[["Pull the numbers together","automate",30,"Collecting data is routine."],["Draft the summary and charts","augment",30,"AI drafts. A person checks it."],["Choose what matters and tell the story","human",30,"Judgement about what matters."],["Share the report","automate",10,"Sending is routine."]],"Capture and share organisational knowledge":[["Turn talks and documents into summaries and lessons","create",35,"A new service: knowledge that is easy to find."],["Check accuracy and sensitivity","human",25,"Experts check what is true and safe to share."],["Tag and organise so people can find it","automate",20,"Tagging and filing are routine."],["Encourage experts to share","human",20,"Asking an expert for their time is personal."]],"Manage the learning platform and vendors":[["Monitor how the platform is used","automate",30,"Usage reports are automatic."],["Compare vendors and read contracts","augment",25,"AI summarises. A person decides."],["Fix platform problems","human",25,"Real problems need a person."],["Manage supplier relationships","human",20,"Relationships are human."]],"Manage the learning budget":[["Track spend against budget","automate",45,"Systems track this."],["Forecast spend","augment",25,"AI projects. A person checks."],["Decide what to approve or cut","human",30,"Priorities are a decision."]],"Keep mandatory and compliance training on track":[["Assign required courses by role and place","automate",30,"Assignment follows fixed rules."],["Track completion and send reminders","automate",30,"Tracking and reminders are routine."],["Check understanding with short scenarios","augment",20,"AI drafts scenarios. A person checks them."],["Talk through why it matters","human",20,"A short conversation makes it real."]],"Explain AI use to learners and test the AI tools":[["Write a plain-language note on how AI is used","augment",25,"AI drafts. HR edits and owns it."],["Tell learners at the start","human",20,"People hear it best from a person."],["Test the AI tools for accuracy and fairness","human",35,"Testing needs people with context."],["Keep a register of AI tools in learning","create",20,"A new task: a short register of what is used where."]],"Learn the tools and check AI's work":[["Learn what each tool can and cannot do","human",30,"Learning takes time and practice."],["Check a sample of AI work against the source","human",35,"People stay accountable for what goes out."],["Share what works and what does not","augment",20,"AI can group lessons. People discuss them."],["Update guidance when tools change","augment",15,"AI drafts. A person approves."]]},STAGES:[["Plan","Needs, goals and the learning plan",["Find skills gaps and learning needs","Match the learning plan to strategy and budget","Set learning goals and how success will be measured","Plan for global and local needs"]],["Design and build","Programmes, content and skills",["Design the learning programme","Create and update content","Choose how it is delivered","Make learning accessible and fair","Pilot test and improve","Build and keep a skills map"]],["Deliver","Sessions, courses, questions and paths",["Schedule sessions and enrol people","Run live sessions and coach","Assign courses and send reminders","Answer learner questions","Support on-the-job learning with managers","Personalised learning paths"]],["Careers and leaders","Development plans, careers and leaders",["Individual development plans","Career conversations","Match people to internal roles, projects and mentors","Mentoring and coaching programmes","Identify and develop high-potential people and future leaders","Leadership assessments and feedback","Plan leader development across countries"]],["Measure and share","Records, results and knowledge",["Track completion and keep records","Evaluate whether training worked","Report learning impact to leaders","Capture and share organisational knowledge"]],["Throughout","Platform, budget, compliance and AI use",["Manage the learning platform and vendors","Manage the learning budget","Keep mandatory and compliance training on track","Explain AI use to learners and test the AI tools","Learn the tools and check AI's work"]]],KW:/a^/};